/**
 * Model Performance · Overview (the default view).
 *
 * From `/research/model-performance/overview`; the Model Performance Brief is
 * generated by the SAME server calculation and checked equal to it.
 *
 *   * Leads with three short findings, each with its supporting games and the
 *     active (or proposed) experiment it belongs to. Findings are evidence, not
 *     decisions: freshness blocks, blending and interval recalibration are
 *     separate proposals that need their own tested changes.
 *   * Three visibly separate sections: forecast accuracy (evaluated forecasts),
 *     probability quality (log loss / Brier vs the market, using the forecast each
 *     DECISION used, available before that decision), and paper returns.
 *   * The all-game table keeps the forecast favourite (and whether it won) apart
 *     from the wagered side (and the wager's result): a called winner is never a
 *     wager outcome.
 *   * Every number is computed server-side from the same filtered snapshot as the
 *     table; the snapshot is printed above the findings.
 */
import { Fragment, useCallback, useMemo, useState } from 'react'
import { Link } from 'react-router-dom'
import { useApiResource } from '../../hooks/useApiResource'
import { apiRequest } from '../../services/api'
import { STALE_TIME, cacheKey } from '../../services/queryCache'
import { etTime, expectSchema, gameHref } from '../../services/commandCenter'
import { describeError, errorTone, signedNumber } from '../../services/errorWording'
import { AsOf } from './RegionState'
import { MmqbLink } from './MmqbReport'
import { NhlOverviewSection } from '../nhl/NhlPerformance'
import { useNhlTestData } from '../../hooks/useNhlResearch'
import type { NhlOverviewBlock } from '../../types/nhlResearch'
import './command.css'

type Ci = [number, number] | null
interface Wager { side: string | null; result: string | null; status: string | null; stake: number | null; position_id: string }
interface GameRow {
  evaluation_id: string; game_id: string | null; sport: string; model_key: string; model: string
  kickoff_utc: string | null; slate_date: string | null; home: string | null; away: string | null
  forecast_type: 'FINAL' | 'CURRENT' | 'PROSPECTIVE'; snapshot: string; published_utc: string | null
  lead_hours: number | null; lead_bucket: string | null; publication_clock: string | null
  p_home_two_way: number | null; p_tie: number | null; final: { home: number; away: number }; actual_outcome: string | null
  forecast_favourite: 'HOME' | 'AWAY' | null; forecast_favourite_p: number | null; forecast_favourite_correct: boolean | null
  log_loss_two_way: number | null; brier_two_way: number | null; brier_native_stored: number | null
  predicted_margin: number | null; actual_margin: number | null; margin_error: number | null
  predicted_total: number | null; actual_total: number | null; total_error: number | null
  interval_coverage: Record<string, Record<string, boolean>>
  wager: Wager | null
  decision: null | {
    decision_id: string; experiment_version: number; decision_time_utc: string | null; minutes_before_kickoff: number
    governing_rule: string; recommendation: string; selected: boolean; selected_side: string | null; funded: boolean
    availability_status: string; forecast_age_hours: number | null; comparable: boolean; evaluation_forecast_same: boolean | null
    p_home_two_way: number | null; delta_log_loss: number | null; delta_brier: number | null; n_final_pregame_decisions: number
    forecast: null | { table: string; snapshot: string; availability_field: string; available_utc: string | null }
    market_p_home: number | null; market_n_books: number | null; market_books: string[] | null
  }
}
interface Paired {
  n: number; dates: number; model_log_loss_two_way: number; market_log_loss_two_way: number; delta_log_loss: number
  delta_log_loss_ci95: Ci; model_brier_two_way: number; market_brier_two_way: number; delta_brier: number
  delta_brier_ci95: Ci; model_better_games: number; median_forecast_age_hours?: number | null
}
interface EvalGroup {
  sport: string; model_key: string; model: string; forecast_type: string; n: number; decided_two_way: number
  favourite_n: number; favourite_correct: number; favourite_accuracy: number | null
  log_loss_two_way: number | null; log_loss_two_way_ci95: Ci; brier_two_way: number | null; brier_native_stored: number | null
  calibration_in_the_large: number | null; calibration_fit: { slope: number } | null
  brier_check: null | { n: number; native_matches_stored: number; conditional_two_way_mean: number; twice_two_way_holds: number; twice_two_way_fails: number; mean_p_tie: number; max_native_minus_twice_two_way: number | null }
  margin: { n: number; bias: number; bias_ci95: Ci; mae: number } | null
  total: { n: number; bias: number; bias_ci95: Ci; mae: number } | null
  interval_coverage: Record<string, Record<string, { nominal: number; n: number; contained: number; observed: number }>>
}
interface SideBlock { side_n: number; side_wins: number; side_win_rate: number | null; side_win_rate_ci95: Ci; side_mean_model_p: number | null; side_mean_market_p: number | null }
interface DecisionGroup {
  sport: string; engine_id: string; experiment_version: number; model: string; governing_decisions: number
  excluded_not_available_before_decision: number; excluded_no_clock_or_forecast: number; with_market: number
  evaluation_joined: number; evaluation_forecast_differs: number
  market_decision_time: Paired | null; market_comparable: Paired | null
  selection: { selected: SideBlock; not_selected: SideBlock; funded: SideBlock }
}
interface CfbGame {
  game_id: string | null; away: string | null; home: string | null; slate_date: string | null; model_p_home: number
  market_p_home_early: number; market_p_home_at_decision: number; abs_gap_change: number; outcome: string; selected: boolean
  final: { home: number; away: number }
}
interface Cfb {
  eligible_final_decisions: number; availability_clock: string; n_at_availability: number; n_at_decision: number; n_both: number
  n_earliest_retained_and_decision: number; median_forecast_age_at_decision_hours: number | null
  median_earliest_reference_hours_before_decision: number | null
  at_availability: Paired | null; at_decision: Paired | null; earliest_retained: Paired | null
  disagreement_earliest_to_decision: null | { n: number; mean_abs_gap_early: number; mean_abs_gap_at_decision: number; mean_abs_gap_change: number; mean_abs_gap_change_ci95: Ci; share_grew: number; mean_market_move_toward_outcome: number; mean_market_move_toward_outcome_ci95: Ci; share_market_moved_toward_outcome: number; share_market_moved_away_from_outcome: number }
  games_earliest: CfbGame[]; unsupported: string | null
}
interface Finding { key: string; title: string; text: string; experiment: string; game_ids: string[]; evaluation_ids?: string[]; decision_ids?: string[] }
interface Overview {
  schema_version: string; generated_at_utc: string; evidence_as_of_utc: string | null
  scope: { sport: string; model: string; forecast_type: string; lead_bucket: string; label: string; n_games: number; n_decisions: number }
  narrative: { scope: string; findings: Finding[]; selection_statements: string[] }
  groups: EvalGroup[]; decision_groups: DecisionGroup[]; cfb_publication_vs_decision: Cfb | null
  /** NHL research block (regulation 3-way and final 2-way, kept apart); null out of scope. */
  nhl?: NhlOverviewBlock | null
  funnel: {
    forecast_evaluations: number; evaluations_with_governing_decision: number; evaluations_funded: number; governing_decisions: number
    decisions_available_before_decision: number; decisions_excluded_not_available: number; decisions_excluded_no_clock_or_forecast: number
    decisions_with_market: number; decisions_comparable_with_market: number; decisions_selected: number; decisions_funded: number
    decision_vs_evaluation_forecast_joined: number; decision_vs_evaluation_forecast_differs: number
    funded_positions: { total: number; open: number; settled: number }
  }
  wagering: Record<string, { n: number; settled: number; wins: number; losses: number; pushes: number; settled_stake: number; net_profit: number; roi: number | null; open_count: number; open_exposure: number }> | null
  games: GameRow[]
  options: { sports: string[]; models: { sport: string; key: string; label: string; n: number }[]; forecast_types: string[]; lead_buckets: { key: string; label: string }[] }
  methodology: Record<string, string>
}

type SortKey = 'date' | 'sport' | 'model' | 'type' | 'lead' | 'fav' | 'll' | 'delta' | 'total' | 'margin'
const f = (v: number | null | undefined, d = 3) => (v == null ? '—' : v.toFixed(d))
const pct = (v: number | null | undefined, d = 0) => (v == null ? '—' : `${(v * 100).toFixed(d)}%`)
const ci = (c: Ci, d = 3) => (c ? `[${signedNumber(c[0], d)}, ${signedNumber(c[1], d)}]` : '')
const TYPE_LABEL: Record<string, string> = { FINAL: 'FINAL', CURRENT: 'CURRENT', PROSPECTIVE: 'PROSPECTIVE' }
const TONE: Record<string, string> = { small: 'mpo-tone--small', medium: 'mpo-tone--medium', large: 'mpo-tone--large' }
const RESULT: Record<string, string> = { WIN: 'W', LOSS: 'L', PUSH: 'Push', VOID: 'Void', PENDING: 'Open', OPEN: 'Open' }

export function overviewPath(filters: { sport: string; model: string; type: string; lead: string }): string {
  const params = new URLSearchParams()
  if (filters.sport !== 'ALL') params.set('sport', filters.sport)
  if (filters.model !== 'ALL') params.set('model', filters.model)
  if (filters.type !== 'ALL') params.set('forecast_type', filters.type)
  if (filters.lead !== 'ALL') params.set('lead', filters.lead)
  const query = params.toString()
  return `/research/model-performance/overview${query ? `?${query}` : ''}`
}

/** "W", "L", "Push", "Open" for a funded wager; "no position" otherwise. Never the forecast's result. */
export function wagerLabel(w: Wager | null): string {
  if (!w) return 'no position'
  const result = w.status === 'OPEN' ? 'Open' : RESULT[w.result ?? ''] ?? (w.result ?? '—')
  return `${w.side ?? '?'} · ${result}`
}

export function sortGames(rows: GameRow[], key: SortKey, dir: 1 | -1): GameRow[] {
  const value = (g: GameRow): number | string | null => {
    switch (key) {
      case 'date': return g.kickoff_utc
      case 'sport': return g.sport
      case 'model': return g.model
      case 'type': return g.forecast_type
      case 'lead': return g.lead_hours
      case 'fav': return g.forecast_favourite_p
      case 'll': return g.log_loss_two_way
      case 'delta': return g.decision?.delta_log_loss ?? null
      case 'total': return g.total_error == null ? null : Math.abs(g.total_error)
      case 'margin': return g.margin_error == null ? null : Math.abs(g.margin_error)
    }
  }
  return [...rows].sort((a, b) => {
    const x = value(a), y = value(b)
    if (x == null && y == null) return 0
    if (x == null) return 1 // missing values always last
    if (y == null) return -1
    return (x < y ? -1 : x > y ? 1 : 0) * dir
  })
}

export function ModelPerformanceOverview({ wagersHref = '/performance?panel=wagers&sport=NFL' }: { wagersHref?: string }) {
  const [filters, setFilters] = useState({ sport: 'ALL', model: 'ALL', type: 'ALL', lead: 'ALL' })
  const [nhlTest] = useNhlTestData()
  // NHL test data (fixtures) is counted only when the reader turns it on.
  const path = `${overviewPath(filters)}${nhlTest ? `${overviewPath(filters).includes('?') ? '&' : '?'}test_data=true` : ''}`
  const loader = useCallback(async (signal: AbortSignal) =>
    expectSchema(await apiRequest<Overview>(path, {}, signal), 'AISP_MODEL_PERFORMANCE_OVERVIEW_V2'), [path])
  const resource = useApiResource<Overview>(loader, { key: cacheKey('model-performance-overview-v2', { ...filters, nhlTest }), staleTimeMs: STALE_TIME.slate })
  const data = resource.data
  const [focus, setFocus] = useState<Finding | null>(null)
  const [sort, setSort] = useState<{ key: SortKey; dir: 1 | -1 }>({ key: 'date', dir: -1 })
  const [showAll, setShowAll] = useState(false)
  const [open, setOpen] = useState<string | null>(null)
  const set = (patch: Partial<typeof filters>) => { setFilters((v) => ({ ...v, ...patch })); setFocus(null); setShowAll(false) }

  const rows = useMemo(() => {
    if (!data) return []
    const ids = focus ? new Set([...(focus.game_ids ?? [])]) : null
    const base = ids ? data.games.filter((g) => g.game_id && ids.has(g.game_id)) : data.games
    return sortGames(base, sort.key, sort.dir)
  }, [data, focus, sort])
  const shown = showAll || focus ? rows : rows.slice(0, 25)
  const models = (data?.options.models ?? []).filter((m) => filters.sport === 'ALL' || m.sport === filters.sport)
  const header = (key: SortKey, label: string, title?: string) => (
    <th aria-sort={sort.key === key ? (sort.dir === 1 ? 'ascending' : 'descending') : 'none'} title={title}>
      <button type="button" className="mpo-sort" onClick={() => setSort((s) => ({ key, dir: s.key === key ? (-s.dir as 1 | -1) : (key === 'date' ? -1 : 1) }))}>
        {label}{sort.key === key ? (sort.dir === 1 ? ' ▲' : ' ▼') : ''}
      </button>
    </th>
  )
  const cfb = data?.cfb_publication_vs_decision ?? null
  const nhl = data?.nhl ?? null

  return (
    <section className="mpo" aria-label="Model performance overview" data-testid="mp-overview">
      <section className="cc-dark cc-perf__head mpo__head" aria-label="Lead findings">
        <header className="cc-perf__top">
          <div>
            <h1 className="cc-kicker cc-perf__title">Model Performance · Overview</h1>
            <h2>Three findings</h2>
          </div>
          <div className="cc-perf__asof">
            {data?.evidence_as_of_utc && <span>Evidence as of {etTime(data.evidence_as_of_utc, true)}</span>}
            <AsOf resource={resource} label="overview" />
          </div>
        </header>
        {!data
          ? <p className="cc-muted" role="status">{resource.error ? `The overview is unavailable: ${resource.error}` : 'Scoring every game…'}</p>
          : (
            <>
              <p className="mpo__snapshot" data-testid="mpo-snapshot">Evidence snapshot {data.evidence_as_of_utc ? etTime(data.evidence_as_of_utc, true) : '—'} · computed {etTime(data.generated_at_utc, true)}. This page recomputes on every load, so it can differ from a brief taken at another time.</p>
              <p className="mpo__scope" data-testid="mpo-scope">Snapshot: <b>{data.scope.label}</b> · {data.scope.n_games} scored forecasts · {data.scope.n_decisions} governing decisions. Findings are computed from exactly this snapshot.</p>
              <MmqbLink />
              <ol className="mpo__findings" aria-label="Findings" data-testid="mpo-findings">
                {data.narrative.findings.map((item) => (
                  <li key={item.key} className={focus?.key === item.key ? 'is-focus' : ''}>
                    <h3>{item.title}</h3>
                    <p>{item.text}</p>
                    <p className="mpo__exp"><b>Experiment:</b> {item.experiment}</p>
                    {item.game_ids.length > 0 && (
                      <button type="button" className="mpo__games" onClick={() => { setFocus(focus?.key === item.key ? null : item); setOpen(null) }}>
                        {focus?.key === item.key ? 'Show every game again' : `Supporting games (${item.game_ids.length})`}
                      </button>
                    )}
                  </li>
                ))}
              </ol>
              <p className="mpo__proposal">Freshness blocks, market-anchored blending and interval recalibration are separate proposals; each needs its own tested change. Nothing here decides them.</p>
            </>
          )}
      </section>

      <p className="mpo__authority" role="note" data-testid="mpo-authority">
        <b>This evaluation view does not create positions.</b> It scores forecasts only. Official NFL wagers (and MLB and CFB
        funded positions) are a separate population, shown with their own returns in <Link to={wagersHref}>Wager Results</Link>.
      </p>

      <div className="mpo__filters" role="group" aria-label="Snapshot filters">
        <label><span>Sport</span>
          <select value={filters.sport} onChange={(e) => set({ sport: e.target.value, model: 'ALL' })}>
            <option value="ALL">All sports</option>
            {(data?.options.sports ?? ['MLB', 'NFL', 'CFB']).map((s) => <option key={s} value={s}>{s}</option>)}
          </select>
        </label>
        <label><span>Model</span>
          <select value={filters.model} onChange={(e) => set({ model: e.target.value })}>
            <option value="ALL">All models</option>
            {models.map((m) => <option key={m.key} value={m.key}>{m.label} · n={m.n}</option>)}
          </select>
        </label>
        <label><span>Forecast type</span>
          <select value={filters.type} onChange={(e) => set({ type: e.target.value })}>
            <option value="ALL">FINAL + CURRENT + PROSPECTIVE</option>
            {(data?.options.forecast_types ?? ['FINAL', 'CURRENT', 'PROSPECTIVE']).map((t) => <option key={t} value={t}>{TYPE_LABEL[t] ?? t}</option>)}
          </select>
        </label>
        <label><span>Lead time</span>
          <select value={filters.lead} onChange={(e) => set({ lead: e.target.value })}>
            <option value="ALL">All lead times</option>
            {(data?.options.lead_buckets ?? []).map((b) => <option key={b.key} value={b.key}>{b.label}</option>)}
          </select>
        </label>
      </div>

      {data && (
        <section className="cc-mpanel mpo__section" aria-label="Forecast accuracy" data-testid="mpo-accuracy">
          <h3>1 · Forecast accuracy <small>evaluated forecasts, one per game and model</small></h3>
          <div className="cc-table__scroll">
            <table className="cc-board mpo__groups">
              <thead><tr><th>Sport · model</th><th>Type</th><th>Games</th><th title="The forecast's >50% side won">Favourite won</th>
                <th title="Predicted minus actual; negative = underestimate">Total bias · MAE</th><th>Margin bias · MAE</th>
                <th>Margin intervals 50/80/90</th><th>Total intervals 50/80/90</th></tr></thead>
              <tbody>{data.groups.map((g) => (
                <tr key={`${g.model_key}|${g.forecast_type}`} className={g.forecast_type === 'ALL' ? 'mpo__grouprow' : 'mpo__typerow'}>
                  <td>{g.sport} · {g.model}</td><td>{g.forecast_type === 'ALL' ? 'All' : g.forecast_type}</td><td>{g.n}</td>
                  <td>{g.favourite_correct} / {g.favourite_n} · {pct(g.favourite_accuracy)}</td>
                  <td>{g.total ? `${signedNumber(g.total.bias, 2)} · ${f(g.total.mae, 2)}` : '—'}<small>{g.total ? ci(g.total.bias_ci95, 2) : ''}</small></td>
                  <td>{g.margin ? `${signedNumber(g.margin.bias, 2)} · ${f(g.margin.mae, 2)}` : '—'}</td>
                  <td>{g.interval_coverage.margin ? ['50', '80', '90'].map((l) => pct(g.interval_coverage.margin[l]?.observed)).join(' / ') : '—'}</td>
                  <td>{g.interval_coverage.total ? ['50', '80', '90'].map((l) => pct(g.interval_coverage.total[l]?.observed)).join(' / ') : '—'}</td>
                </tr>))}</tbody>
            </table>
          </div>
        </section>
      )}

      {data && (
        <section className="cc-mpanel mpo__section" aria-label="Probability quality" data-testid="mpo-probability">
          <h3>2 · Probability quality <small>two-way log loss and Brier; market comparisons use the forecast each decision used, available before it</small></h3>
          <div className="cc-table__scroll">
            <table className="cc-board mpo__groups">
              <thead><tr><th>Sport · model</th><th>Type</th><th>Log loss (2-way)</th><th>Brier 2-way · native</th><th title="Mean forecast minus observed home-win rate">Calibration</th></tr></thead>
              <tbody>{data.groups.map((g) => (
                <tr key={`p-${g.model_key}|${g.forecast_type}`} className={g.forecast_type === 'ALL' ? 'mpo__grouprow' : 'mpo__typerow'}>
                  <td>{g.sport} · {g.model}</td><td>{g.forecast_type === 'ALL' ? 'All' : g.forecast_type}</td>
                  <td>{f(g.log_loss_two_way)}<small>{ci(g.log_loss_two_way_ci95)}</small></td>
                  <td>{f(g.brier_two_way)} · {f(g.brier_native_stored)}
                    <small>{g.brier_check ? (g.brier_check.twice_two_way_fails ? `native ≠ 2×two-way on ${g.brier_check.twice_two_way_fails}/${g.brier_check.n} (tie mass ${pct(g.brier_check.mean_p_tie, 1)})` : `native = 2×two-way on ${g.brier_check.twice_two_way_holds}/${g.brier_check.n}`) : ''}</small></td>
                  <td>{signedNumber(g.calibration_in_the_large, 3)}<small>{g.calibration_fit ? `slope ${f(g.calibration_fit.slope, 2)}` : 'slope n<20'}</small></td>
                </tr>))}</tbody>
            </table>
          </div>
          <h4 className="mpo__h4">Against the median-of-books market · decision-bound forecasts</h4>
          <div className="cc-table__scroll">
            <table className="cc-board mpo__groups" data-testid="mpo-market">
              <thead><tr><th>Sport · model</th><th>Decisions</th><th title="Forecast availability clock later than the decision / no clock or forecast">Excluded</th>
                <th title="Governing decision used a different forecast revision from the scored one">Differs from scored forecast</th>
                <th title="Forecast available ≤ 6 h before the decision and not after it">vs market · comparable</th><th>vs market · decision time</th></tr></thead>
              <tbody>{data.decision_groups.map((g) => (
                <tr key={`${g.engine_id}|${g.experiment_version}`}>
                  <td>{g.sport} · {g.model}</td><td>{g.governing_decisions}</td>
                  <td>{g.excluded_not_available_before_decision} late · {g.excluded_no_clock_or_forecast} no forecast</td>
                  <td>{g.evaluation_joined ? `${g.evaluation_forecast_differs} of ${g.evaluation_joined}` : 'not scored'}</td>
                  <td className={g.market_comparable ? (g.market_comparable.delta_log_loss < 0 ? 'is-up' : 'is-down') : ''}>
                    {g.market_comparable ? signedNumber(g.market_comparable.delta_log_loss, 3) : '—'}
                    <small>{g.market_comparable ? `${ci(g.market_comparable.delta_log_loss_ci95)} n=${g.market_comparable.n} · Brier ${signedNumber(g.market_comparable.delta_brier, 4)}` : 'no comparable pair'}</small></td>
                  <td>{g.market_decision_time ? signedNumber(g.market_decision_time.delta_log_loss, 3) : '—'}
                    <small>{g.market_decision_time ? `${ci(g.market_decision_time.delta_log_loss_ci95)} n=${g.market_decision_time.n} · forecast ${f(g.market_decision_time.median_forecast_age_hours ?? null, 0)} h old` : ''}</small></td>
                </tr>))}</tbody>
            </table>
          </div>
          <p className="cc-note">Δ = model minus market, two-way conditional on no tie (the market is two-way); negative favours the model. NFL's stored Brier is the native three-class score and is never compared with the market.</p>
          {data.narrative.selection_statements.length > 0 && (
            <>
              <h4 className="mpo__h4">Selected sides · per sport, with the interval</h4>
              <ul className="mpo__statements" data-testid="mpo-selection">{data.narrative.selection_statements.map((s) => <li key={s}>{s}</li>)}</ul>
            </>
          )}
        </section>
      )}

      {cfb && (
        <section className="cc-mpanel mpo__section" aria-label="CFB model versus market over time" data-testid="mpo-cfb">
          <h3>CFB · model versus market at forecast availability and at decision</h3>
          <p className="cc-note">Model probability is fixed from availability ({cfb.availability_clock}) to decision, so any change in the gap is market movement.
            Forecasts were available a median {f(cfb.median_forecast_age_at_decision_hours, 0)} h before the decision.</p>
          <div className="cc-table__scroll">
            <table className="cc-board mpo__groups">
              <thead><tr><th>Market taken at</th><th>Games</th><th>Model LL</th><th>Market LL</th><th>Δ log loss</th><th>Δ Brier (2-way)</th></tr></thead>
              <tbody>
                {([['Forecast availability', cfb.at_availability, cfb.n_at_availability],
                  [`Earliest retained quote (median ${f(cfb.median_earliest_reference_hours_before_decision, 1)} h before decision)`, cfb.earliest_retained, cfb.n_earliest_retained_and_decision],
                  ['Decision time', cfb.at_decision, cfb.n_at_decision]] as const).map(([label, b, n]) => (
                  <tr key={label}><td>{label}</td><td>{n}</td><td>{f(b?.model_log_loss_two_way)}</td><td>{f(b?.market_log_loss_two_way)}</td>
                    <td>{b ? signedNumber(b.delta_log_loss, 3) : '—'}<small>{b ? ci(b.delta_log_loss_ci95) : 'no qualifying pair'}</small></td>
                    <td>{b ? signedNumber(b.delta_brier, 4) : '—'}<small>{b ? ci(b.delta_brier_ci95, 4) : ''}</small></td></tr>))}
              </tbody>
            </table>
          </div>
          {cfb.unsupported && <p className="mpo__unsupported" role="note">{cfb.unsupported}</p>}
          {cfb.disagreement_earliest_to_decision && (
            <p className="cc-note">From the earliest retained quote to the decision (n={cfb.disagreement_earliest_to_decision.n}): mean |model − market|
              {' '}{f(cfb.disagreement_earliest_to_decision.mean_abs_gap_early * 100, 1)} → {f(cfb.disagreement_earliest_to_decision.mean_abs_gap_at_decision * 100, 1)} pts
              {' '}(change {signedNumber(cfb.disagreement_earliest_to_decision.mean_abs_gap_change * 100, 2)} pts {ci(cfb.disagreement_earliest_to_decision.mean_abs_gap_change_ci95 && [cfb.disagreement_earliest_to_decision.mean_abs_gap_change_ci95[0] * 100, cfb.disagreement_earliest_to_decision.mean_abs_gap_change_ci95[1] * 100], 2)});
              {' '}grew on {pct(cfb.disagreement_earliest_to_decision.share_grew)}; the market moved toward the result on {pct(cfb.disagreement_earliest_to_decision.share_market_moved_toward_outcome)} and away on {pct(cfb.disagreement_earliest_to_decision.share_market_moved_away_from_outcome)}. The disagreement was already present at the earliest quote.</p>
          )}
          <details className="cc-below"><summary>The {cfb.games_earliest.length} games with both references</summary>
            <div className="cc-table__scroll"><table className="cc-board">
              <thead><tr><th>Game</th><th>Model p(home)</th><th>Market early</th><th>Market at decision</th><th>Gap change</th><th>Final</th><th>Selected</th></tr></thead>
              <tbody>{cfb.games_earliest.map((x) => (
                <tr key={x.game_id ?? `${x.away}-${x.home}`}><td>{x.game_id ? <Link className="cc-linkish" to={gameHref('CFB', x.game_id)}>{x.away} at {x.home}</Link> : `${x.away} at ${x.home}`}</td>
                  <td>{pct(x.model_p_home, 1)}</td><td>{pct(x.market_p_home_early, 1)}</td><td>{pct(x.market_p_home_at_decision, 1)}</td>
                  <td>{signedNumber(x.abs_gap_change * 100, 2)} pts</td><td>{x.final.away}–{x.final.home}</td><td>{x.selected ? 'yes' : 'no'}</td></tr>))}</tbody>
            </table></div>
          </details>
        </section>
      )}

      {nhl && <NhlOverviewSection block={nhl} />}

      {data && (
        <section className="mpo__pops" aria-label="Three populations">
          <div>
            <small>Forecast evaluations</small>
            <b>{data.funnel.forecast_evaluations}</b>
            <span>{data.funnel.evaluations_with_governing_decision} have a governing decision · {data.funnel.evaluations_funded} a funded position</span>
          </div>
          <div>
            <small>Decision opportunities</small>
            <b>{data.funnel.governing_decisions}</b>
            <span>governing FINAL_PREGAME decisions · {data.funnel.decisions_available_before_decision} with their forecast available before the decision · {data.funnel.decisions_excluded_not_available} excluded (forecast arrived later) · {data.funnel.decisions_excluded_no_clock_or_forecast} with no forecast linked · {data.funnel.decision_vs_evaluation_forecast_differs} of {data.funnel.decision_vs_evaluation_forecast_joined} used a different forecast from the scored one</span>
          </div>
          <div>
            <small>Funded positions</small>
            <b>{data.funnel.funded_positions.total}</b>
            <span>{data.funnel.funded_positions.settled} settled · {data.funnel.funded_positions.open} open. Returns: <Link to={wagersHref}>Wager Results</Link></span>
          </div>
        </section>
      )}

      {data && (
        <section className="cc-mpanel" aria-label="All scored games">
          <div className="mpo__tablehead">
            <h3>{focus ? `Supporting games · ${focus.title}` : `All scored games · one primary evaluation per game · ${rows.length}`}</h3>
            {focus && <button type="button" className="cc-more" onClick={() => setFocus(null)}>Clear finding filter</button>}
          </div>
          <div className="cc-table__scroll">
            <table className="cc-board mpo__table" data-testid="mpo-table">
              <thead><tr>
                {header('date', 'Date')}{header('sport', 'Sport')}{header('model', 'Model')}<th>Game</th>
                {header('type', 'Type')}{header('lead', 'Lead h', 'Hours between publication and kickoff')}
                {header('fav', 'Forecast favourite', "The scored forecast's >50% side (two-way) and whether it won")}<th>Final</th>
                {header('ll', 'Log loss')}{header('delta', 'Δ vs mkt', "Decision-bound forecast minus market log loss at decision time (* = not a comparable time)")}
                {header('total', 'Total', 'Predicted vs actual total; error = predicted − actual')}{header('margin', 'Margin err', 'Predicted − actual, home − away')}
                <th title="Only where an official funded position exists">Wagered side</th>
              </tr></thead>
              <tbody>
                {shown.map((g) => {
                  const delta = g.decision?.delta_log_loss ?? null
                  const expanded = open === g.evaluation_id
                  const totalTone = errorTone(g.total_error, 'total', g.sport)
                  const marginTone = errorTone(g.margin_error, 'margin', g.sport)
                  const favTeam = g.forecast_favourite === 'HOME' ? g.home : g.forecast_favourite === 'AWAY' ? g.away : null
                  return (
                    <Fragment key={g.evaluation_id}>
                      <tr className={expanded ? 'is-selected' : ''}>
                        <td>{g.slate_date ?? '—'}</td><td>{g.sport}</td><td>{g.model}</td>
                        <td><button type="button" className="mpo-rowbtn" aria-expanded={expanded} onClick={() => setOpen(expanded ? null : g.evaluation_id)}>{g.away} at {g.home}</button></td>
                        <td><span className={`mpo-type mpo-type--${g.forecast_type}`}>{g.forecast_type}</span></td>
                        <td>{f(g.lead_hours, 1)}</td>
                        <td className={g.forecast_favourite_correct == null ? '' : g.forecast_favourite_correct ? 'is-up' : 'is-down'} data-testid="mpo-fav">
                          {favTeam ? `${favTeam} ${pct(g.forecast_favourite_p)}` : '—'}<small>{g.forecast_favourite_correct == null ? '' : g.forecast_favourite_correct ? 'favourite won' : 'favourite lost'}</small></td>
                        <td>{g.final.away}–{g.final.home}</td>
                        <td>{f(g.log_loss_two_way)}</td>
                        <td className={delta == null ? '' : delta < 0 ? 'is-up' : 'is-down'}>{delta == null ? '—' : `${signedNumber(delta, 3)}${g.decision?.comparable ? '' : '*'}`}</td>
                        <td className={totalTone ? TONE[totalTone] : ''}>{f(g.predicted_total, 1)} vs {g.actual_total ?? '—'}<small>{describeError(g.total_error)}</small></td>
                        <td className={marginTone ? TONE[marginTone] : ''}>{signedNumber(g.margin_error, 1)}</td>
                        <td data-testid="mpo-wager" className={g.wager?.result === 'WIN' ? 'is-up' : g.wager?.result === 'LOSS' ? 'is-down' : ''}>{wagerLabel(g.wager)}</td>
                      </tr>
                      {expanded && (
                        <tr className="mpo__detail"><td colSpan={13}>
                          <dl>
                            <div><dt>Scored forecast</dt><dd>{g.snapshot} · published {g.published_utc ? etTime(g.published_utc, true) : '—'} · {f(g.lead_hours, 1)} h before kickoff · two-way log loss {f(g.log_loss_two_way)} · Brier two-way {f(g.brier_two_way)} / native {f(g.brier_native_stored)}</dd></div>
                            <div><dt>Margin · total</dt><dd>margin predicted {signedNumber(g.predicted_margin, 1)} (home − away), actual {signedNumber(g.actual_margin, 0)} · {describeError(g.margin_error)}; total predicted {f(g.predicted_total, 1)}, actual {g.actual_total ?? '—'} · {describeError(g.total_error)}</dd></div>
                            <div><dt>Decision</dt><dd>{g.decision ? `${g.decision.recommendation}${g.decision.selected_side ? ` ${g.decision.selected_side}` : ''} · ${g.decision.minutes_before_kickoff} min before kickoff · forecast ${g.decision.forecast?.snapshot ?? '—'} (${g.decision.forecast?.availability_field ?? '—'} ${g.decision.forecast?.available_utc ? etTime(g.decision.forecast.available_utc, true) : '—'}, ${f(g.decision.forecast_age_hours, 1)} h before the decision) · ${g.decision.availability_status.replace(/_/g, ' ').toLowerCase()}${g.decision.evaluation_forecast_same === false ? ' · a different forecast revision from the scored one' : ''}` : 'no governing decision for this model and game'}</dd></div>
                            <div><dt>Market</dt><dd>{g.decision?.market_p_home != null ? `median of ${g.decision.market_n_books} books at the decision: ${pct(g.decision.market_p_home, 1)} home · decision-bound model ${pct(g.decision.p_home_two_way, 1)}` : 'no market reference at the decision'}</dd></div>
                            <div><dt>Wager</dt><dd>{g.wager ? `${g.wager.side} · ${wagerLabel(g.wager)} · stake $${f(g.wager.stake, 2)}` : 'no position'}</dd></div>
                            {g.game_id && <div><dt>Game</dt><dd><Link className="cc-linkish" to={gameHref(g.sport, g.game_id)}>Open the game page</Link></dd></div>}
                          </dl>
                        </td></tr>
                      )}
                    </Fragment>
                  )
                })}
              </tbody>
            </table>
          </div>
          {!focus && rows.length > 25 && <button type="button" className="cc-more" onClick={() => setShowAll((v) => !v)}>{showAll ? 'Show fewer' : `Show all ${rows.length}`}</button>}
          <p className="cc-note">Forecast favourite is the scored forecast's side above 50%; wagered side is an official position's side and result. They are separate: a favourite that won is not a winning wager. * decision-time Δ where the forecast was more than 6 h old.</p>
        </section>
      )}

      {data?.wagering && (
        <section className="cc-mpanel mpo__section mpo__wagers" aria-label="Paper returns" data-testid="mpo-returns">
          <h3>3 · Paper returns <small>official funded positions; not a measure of forecast quality</small></h3>
          <div className="cc-table__scroll">
            <table className="cc-board">
              <thead><tr><th>Sport</th><th>Funded</th><th>Settled W–L–P</th><th>Settled stake</th><th>Net</th><th>ROI</th><th>Open</th><th>Open exposure</th></tr></thead>
              <tbody>{Object.entries(data.wagering).map(([code, w]) => (
                <tr key={code}><td>{code}</td><td>{w.n}</td><td>{w.wins}–{w.losses}–{w.pushes}</td><td>${w.settled_stake.toFixed(2)}</td>
                  <td>{w.net_profit < 0 ? '−' : ''}${Math.abs(w.net_profit).toFixed(2)}</td><td>{pct(w.roi, 1)}</td><td>{w.open_count}</td><td>${w.open_exposure.toFixed(2)}</td></tr>
              ))}</tbody>
            </table>
          </div>
          <p className="cc-note">From the Wager Results calculation; see <Link to={wagersHref}>Wager Results</Link> for every position.</p>
        </section>
      )}

      {data && (
        <details className="cc-below cc-perf__defs" data-testid="mpo-methodology">
          <summary>Methodology · how every number above is computed</summary>
          <dl>{Object.entries(data.methodology).map(([k, v]) => <div key={k}><dt>{k.replace(/_/g, ' ')}</dt><dd>{v}</dd></div>)}</dl>
        </details>
      )}
    </section>
  )
}
